// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IEBrake } from "../EmergencyBrake/IEBrake.sol";
import { IHub, IHubRegistry, IYieldGroupNav } from "../Interfaces/IHubLiquidity.sol";
import { AccessControlledV8 } from "@venusprotocol/governance-contracts/contracts/Governance/AccessControlledV8.sol";

/**
 * @title HubNavDeviationSentinel
 * @author Venus
 * @notice Sentinel a keeper drives to watch a Liquidity Hub resource's NavGuard band. When the reported
 *         value sits too far from the band's centre it pauses the whole Hub, which stops every deposit
 *         and redemption on it. It acts through EBrake.
 * @dev This contract can only TIGHTEN restrictions (pause), never loosen them.
 *      Recovery (unpausing) is handled via governance VIP.
 *      Idempotency is handled by EBrake — duplicate calls are no-ops.
 *
 *      The monitoring here stands on its own: it reads the band and judges the value against its own
 *      thresholds, whether or not the Hub is clamping that resource. Those thresholds should be set
 *      wider than the Hub's own gap, so routine clamping alone never trips a pause.
 */
contract HubNavDeviationSentinel is AccessControlledV8 {
    /// @notice Pause thresholds for one Liquidity Hub resource's NavGuard band
    /// @dev A zero threshold leaves that side unwatched, so a resource can be guarded one way only.
    /// @param hub The Hub to pause, read off the YieldGroup when configured and never from a keeper
    /// @param pauseUpBps How far above the band's centre the value must sit to trip, in bps
    /// @param pauseDownBps How far below the band's centre the value must sit to trip, in bps
    /// @param enabled Whether this band is being watched. Only `setNavMonitoringEnabled` writes it.
    struct NavGuardConfig {
        address hub;
        uint16 pauseUpBps;
        uint16 pauseDownBps;
        bool enabled;
    }

    /// @notice Why a NavGuard check did or did not call for a pause
    /// @dev Ordered so the zero value is a no-action one: an unwritten status reads as MonitoringDisabled.
    /// @param MonitoringDisabled This YieldGroup/resource pair is not armed in `navGuardConfigs`
    /// @param YieldGroupNotRegistered The Hub does not list the supplied YieldGroup
    /// @param ResourceNotRegistered The YieldGroup does not list the supplied resource
    /// @param ObservedValueZero The value source read back zero, so there is nothing to compare
    /// @param CentreZero The band is closed, but nothing is worth pausing for — see `checkNavGuardDeviation`
    /// @param WithinThreshold Not past either threshold, or past one by a gap too small against the
    ///        Hub's NAV to pause for — see `minHubNavGapBps`
    /// @param Breached A pause is due: the value is past a threshold, or a closed band is valuing a
    ///        live position at zero, and the gap is over `minHubNavGapBps` of the Hub's NAV
    enum NavGuardCheckStatus {
        MonitoringDisabled,
        YieldGroupNotRegistered,
        ResourceNotRegistered,
        ObservedValueZero,
        CentreZero,
        WithinThreshold,
        Breached
    }

    /// @notice Basis-point denominator, and the ceiling on either pause threshold
    /// @dev `pauseDownBps` must stay strictly below it: at 10_000 the downside trip point is 0, and
    ///      nothing is below 0, so that side would never fire. Upward has no such point.
    uint16 public constant MAX_DEVIATION_BPS = 10_000;

    /// @notice Emergency Brake contract the Hub pause is routed through
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IEBrake public immutable EBRAKE;

    /// @notice Chain-level Liquidity Hub directory, used to vouch for a YieldGroup's Hub at config time
    /// @custom:oz-upgrades-unsafe-allow state-variable-immutable
    IHubRegistry public immutable HUB_REGISTRY;

    /// @notice Mapping of trusted keeper addresses
    mapping(address => bool) public trustedKeepers;

    /// @notice NavGuard pause thresholds
    /// @dev Keyed on the pair because the band lives in each YieldGroup's own storage, so the same
    ///      resource under two YieldGroups has two independent bands.
    mapping(address yieldGroup => mapping(address resource => NavGuardConfig config)) public navGuardConfigs;

    /// @notice Smallest gap between the observed value and the centre that can pause the Hub, in bps
    ///         of the Hub's NAV. Starts at 100, which is 1%.
    /// @dev Both thresholds are a percentage of the centre, and a redeem takes the amount redeemed off
    ///      the centre but leaves the gap. So after a partial exit a small gap reads as a large move:
    ///      a 1,000 gap is 1% of a 100,000 centre, but 24.7% of the 4,050 left after redeeming 95,950.
    ///      On a Hub worth 1,000,000 that gap is 0.1% of NAV, not worth freezing every deposit and
    ///      redemption for.
    ///
    ///      A closed band is the extreme case. It values its resource at zero, so everything the
    ///      resource still holds is the gap, and anyone can leave dust there.
    uint16 public minHubNavGapBps;

    /// @dev Storage gap for future upgrades.
    uint256[47] private __gap;

    /// @notice Emitted when a keeper's trusted status is updated
    /// @param keeper The keeper address
    /// @param isTrusted Whether the keeper is trusted
    event TrustedKeeperUpdated(address indexed keeper, bool isTrusted);

    /// @notice Emitted when `minHubNavGapBps` is changed
    /// @param oldBps The previous minimum gap, in bps of the Hub's NAV
    /// @param newBps The new minimum gap, in bps of the Hub's NAV
    event MinHubNavGapUpdated(uint16 oldBps, uint16 newBps);

    /// @notice Emitted when a resource's NavGuard pause thresholds are updated
    /// @param hub The Liquidity Hub the YieldGroup belongs to
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The Liquidity Hub resource address
    /// @param config The stored config after the update
    event NavGuardConfigUpdated(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        NavGuardConfig config
    );

    /// @notice Emitted when a resource's band starts or stops being watched
    /// @param hub The Liquidity Hub the YieldGroup belongs to
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The Liquidity Hub resource address
    /// @param enabled Whether the band is being watched
    event NavGuardStatusChanged(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        bool enabled
    );

    /// @notice Emitted when a resource breaks through its NavGuard band and the Hub is paused
    /// @dev `centre` is what the breach was measured against, and the two bounds are the band the
    ///      Hub was applying at the time, all three with drift included. An operator can recompute
    ///      the ordinary trip point from the thresholds — except when `centre` is 0, where the
    ///      breach is the band itself being closed on a real value, not a percentage miss.
    /// @param hub The Liquidity Hub that was paused
    /// @param yieldGroup The YieldGroup holding the breaching resource
    /// @param resource The resource whose value broke through its band
    /// @param observedValue Value the counterparty reported at detection time
    /// @param centre What the band says the position is worth, which the thresholds measure from
    /// @param minAllowedValue The band's floor at detection time
    /// @param maxAllowedValue The band's cap at detection time
    event NavGuardDeviationHandled(
        address indexed hub,
        address indexed yieldGroup,
        address indexed resource,
        uint256 observedValue,
        uint256 centre,
        uint256 minAllowedValue,
        uint256 maxAllowedValue
    );

    /// @notice Thrown when both thresholds are set to zero
    error ZeroDeviation();

    /// @notice Thrown when a threshold is out of range
    error ExceedsMaxDeviation();

    /// @notice Thrown when a zero address is provided
    error ZeroAddress();

    /// @notice Thrown when caller is not an authorized keeper
    error UnauthorizedKeeper();

    /// @notice Thrown when a resource has no NavGuard pause thresholds set
    error ResourceNotConfigured(address yieldGroup, address resource);

    /// @notice Thrown when a resource's NavGuard band is not being watched
    error NavGuardDisabled(address yieldGroup, address resource);

    /// @notice Thrown when the YieldGroup's Hub is not one the registry lists
    error HubNotRegistered(address hub, address yieldGroup);

    /// @notice Thrown when the Hub does not list the supplied YieldGroup in its registry
    error YieldGroupNotRegistered(address hub, address yieldGroup);

    /// @notice Thrown when the YieldGroup does not list the supplied resource in its registry
    /// @dev Unregistered means zero balance, so it is outside `totalAssets()` and nothing to pause.
    error ResourceNotRegistered(address yieldGroup, address resource);

    /// @notice Thrown when the value source reports zero
    /// @dev Either a read that failed or a position the counterparty prices at nothing: the Hub
    ///      drops the readable flag in `navGuardStatus`, so the two arrive here as the same zero.
    ///      Neither is treated as a breach, which matches the Hub refusing to close a band on a
    ///      published zero. A genuine write-off is a governance action, not a sentinel pause.
    error NavGuardObservedValueZero(address resource);

    /// @notice Thrown when the band is closed but nothing here is mis-valued enough to pause for
    /// @dev The same closed band with the cap armed, the downside watched and more than
    ///      `minHubNavGapBps` of the Hub's NAV left in it is a `Breached` pause instead — see
    ///      `checkNavGuardDeviation`.
    error NavGuardCentreZero(address resource);

    /// @notice Thrown when the value is not past a pause threshold, or is past one by a gap no larger
    ///         than `minHubNavGapBps` of the Hub's NAV
    /// @dev Small enough to let the band step down on its own.
    error DeviationWithinThreshold(address resource, uint256 observedValue);

    modifier onlyKeeper() {
        if (!trustedKeepers[msg.sender]) revert UnauthorizedKeeper();
        _;
    }

    /// @notice Constructor for HubNavDeviationSentinel
    /// @param eBrake_ Address of the EBrake contract
    /// @param hubRegistry_ Address of the Liquidity Hub registry
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor(IEBrake eBrake_, IHubRegistry hubRegistry_) {
        if (address(eBrake_) == address(0)) revert ZeroAddress();
        if (address(hubRegistry_) == address(0)) revert ZeroAddress();

        EBRAKE = eBrake_;
        HUB_REGISTRY = hubRegistry_;

        // Note that the contract is upgradeable. Use initialize() or reinitializers
        // to set the state variables.
        _disableInitializers();
    }

    /// @notice Initialize the contract
    /// @param accessControlManager_ Address of the access control manager
    function initialize(address accessControlManager_) external initializer {
        __AccessControlled_init(accessControlManager_);
        minHubNavGapBps = 100; // 1% of the Hub's NAV
    }

    /// @notice Set trusted status for a keeper
    /// @param keeper Address of the keeper
    /// @param isTrusted Whether the keeper should be trusted
    /// @custom:event Emits TrustedKeeperUpdated event
    /// @custom:error ZeroAddress is thrown when keeper address is zero
    function setTrustedKeeper(address keeper, bool isTrusted) external {
        _checkAccessAllowed("setTrustedKeeper(address,bool)");

        if (keeper == address(0)) revert ZeroAddress();

        trustedKeepers[keeper] = isTrusted;
        emit TrustedKeeperUpdated(keeper, isTrusted);
    }

    /// @notice Set the NavGuard pause thresholds for a Liquidity Hub resource
    /// @dev Thresholds only: arming is `setNavMonitoringEnabled`, so retuning one cannot arm or disarm
    ///      it. Both are measured from the band's centre, so each has to exceed the Hub's matching
    ///      gap, `upGapBps` or `downGapBps`, or clamping the Hub does routinely trips a pause.
    /// @param yieldGroup Address of the YieldGroup holding the resource
    /// @param resource Address of the resource inside that YieldGroup
    /// @param pauseUpBps How far above the centre the value must sit to trip, in bps; zero leaves it unwatched
    /// @param pauseDownBps How far below the centre the value must sit to trip, in bps; zero leaves it unwatched
    /// @custom:event Emits NavGuardConfigUpdated event
    /// @custom:error ZeroAddress is thrown when the YieldGroup or resource address is zero
    /// @custom:error ZeroDeviation is thrown when both thresholds are zero
    /// @custom:error ExceedsMaxDeviation is thrown when a threshold is out of range
    /// @custom:error HubNotRegistered is thrown when the registry does not list the YieldGroup's Hub
    /// @custom:error YieldGroupNotRegistered is thrown when that Hub does not list the YieldGroup
    /// @custom:error ResourceNotRegistered is thrown when the YieldGroup does not list the resource
    function setHubNavConfig(address yieldGroup, address resource, uint16 pauseUpBps, uint16 pauseDownBps) external {
        _checkAccessAllowed("setHubNavConfig(address,address,uint16,uint16)");

        if (yieldGroup == address(0) || resource == address(0)) revert ZeroAddress();
        if (pauseUpBps == 0 && pauseDownBps == 0) revert ZeroDeviation();
        if (pauseUpBps > MAX_DEVIATION_BPS || pauseDownBps >= MAX_DEVIATION_BPS) revert ExceedsMaxDeviation();

        address hub = _requireLiveResource(yieldGroup, resource);

        NavGuardConfig storage config = navGuardConfigs[yieldGroup][resource];
        config.pauseUpBps = pauseUpBps;
        config.pauseDownBps = pauseDownBps;
        config.hub = hub;

        emit NavGuardConfigUpdated(hub, yieldGroup, resource, config);
    }

    /// @notice Set the smallest gap between the observed value and the centre that can pause the Hub,
    ///         in bps of the Hub's NAV
    /// @dev This minimum overrides a resource's own thresholds when the resource is small next to its
    ///      Hub. At 1% of a Hub worth 4,260,000 it is 42,600, so a 500,000 position has to move over
    ///      8.5% to pause, whatever its `pauseDownBps` says. Set it below the smallest gap that should
    ///      still pause: that position with an 8% threshold trips at 40,000, which is 0.94% of the Hub.
    ///
    ///      One value applies to every Hub this sentinel watches.
    /// @param newMinHubNavGapBps The new minimum gap, in bps of the Hub's NAV. At 0 any gap past a
    ///        threshold pauses, including dust left in a closed band.
    /// @custom:event Emits MinHubNavGapUpdated event
    /// @custom:error ExceedsMaxDeviation is thrown when the minimum is above 100% of the Hub's NAV
    function setMinHubNavGapBps(uint16 newMinHubNavGapBps) external {
        _checkAccessAllowed("setMinHubNavGapBps(uint16)");

        if (newMinHubNavGapBps > MAX_DEVIATION_BPS) revert ExceedsMaxDeviation();

        emit MinHubNavGapUpdated(minHubNavGapBps, newMinHubNavGapBps);
        minHubNavGapBps = newMinHubNavGapBps;
    }

    /// @notice Start or stop watching a resource's NavGuard band, keeping its thresholds
    /// @dev Arming re-runs the checks `setHubNavConfig` ran, since a Hub or a resource can be
    ///      de-registered in between. Disarming runs none, so a dropped pair can always be turned off.
    /// @param yieldGroup Address of the YieldGroup holding the resource
    /// @param resource Address of the resource
    /// @param enabled Whether to watch this resource's band
    /// @custom:event Emits NavGuardStatusChanged event
    /// @custom:error ZeroAddress is thrown when the YieldGroup or resource address is zero
    /// @custom:error ResourceNotConfigured is thrown when the pair has no thresholds set
    /// @custom:error HubNotRegistered is thrown when arming and the registry has dropped the Hub
    /// @custom:error YieldGroupNotRegistered is thrown when arming and the Hub has dropped the YieldGroup
    /// @custom:error ResourceNotRegistered is thrown when arming and the YieldGroup has dropped the resource
    function setNavMonitoringEnabled(address yieldGroup, address resource, bool enabled) external {
        _checkAccessAllowed("setNavMonitoringEnabled(address,address,bool)");

        if (yieldGroup == address(0) || resource == address(0)) revert ZeroAddress();

        NavGuardConfig storage config = navGuardConfigs[yieldGroup][resource];
        if (config.pauseUpBps == 0 && config.pauseDownBps == 0) revert ResourceNotConfigured(yieldGroup, resource);

        if (enabled) config.hub = _requireLiveResource(yieldGroup, resource);

        config.enabled = enabled;
        emit NavGuardStatusChanged(config.hub, yieldGroup, resource, enabled);
    }

    /// @notice Handle a NavGuard band breach on a Liquidity Hub resource by pausing the Hub
    /// @dev The whole Hub is paused, not the breaching resource: `YieldGroupBase.totalAssets()` sums
    ///      every registered resource without reading its pause flag, so pausing just that resource
    ///      would leave the same wrong number priced into deposits and redemptions.
    /// @param yieldGroup The YieldGroup holding the resource. Checked against its Hub's registry.
    /// @param resource The resource whose NavGuard band to read
    /// @custom:event Emits NavGuardDeviationHandled with the band context at detection time
    /// @custom:error UnauthorizedKeeper is thrown when caller is not a trusted keeper
    /// @custom:error NavGuardDisabled (pair not watched), YieldGroupNotRegistered (Hub dropped the
    ///        YieldGroup), ResourceNotRegistered (YieldGroup dropped the resource),
    ///        NavGuardObservedValueZero (value source reads zero), NavGuardCentreZero (band closed
    ///        with nothing worth pausing for), or DeviationWithinThreshold (break below the
    ///        threshold, or too small against Hub NAV) — each is one non-breach status
    ///        `checkNavGuardDeviation` can return.
    function handleNavGuardDeviation(address yieldGroup, address resource) external onlyKeeper {
        (
            NavGuardCheckStatus status,
            address hub,
            uint256 observedValue,
            uint256 centre,
            uint256 minAllowedValue,
            uint256 maxAllowedValue
        ) = checkNavGuardDeviation(yieldGroup, resource);

        if (status == NavGuardCheckStatus.MonitoringDisabled) revert NavGuardDisabled(yieldGroup, resource);
        if (status == NavGuardCheckStatus.YieldGroupNotRegistered) revert YieldGroupNotRegistered(hub, yieldGroup);
        if (status == NavGuardCheckStatus.ResourceNotRegistered) revert ResourceNotRegistered(yieldGroup, resource);
        if (status == NavGuardCheckStatus.ObservedValueZero) revert NavGuardObservedValueZero(resource);
        if (status == NavGuardCheckStatus.CentreZero) revert NavGuardCentreZero(resource);
        if (status == NavGuardCheckStatus.WithinThreshold) revert DeviationWithinThreshold(resource, observedValue);

        // Backstop for a status the list above does not name: fall through to doing nothing rather
        // than to pausing a Hub on a verdict this function was never taught to read.
        if (status != NavGuardCheckStatus.Breached) return;

        EBRAKE.pauseHub(hub);

        emit NavGuardDeviationHandled(
            hub,
            yieldGroup,
            resource,
            observedValue,
            centre,
            minAllowedValue,
            maxAllowedValue
        );
    }

    /// @notice Check whether a Liquidity Hub resource's NAV has broken through its NavGuard band by
    ///         more than the configured threshold, and why
    /// @dev `handleNavGuardDeviation` calls this rather than repeating the comparison, so what
    ///      monitoring reads and what the keeper acts on cannot drift apart.
    ///      Can revert: `yieldGroup` is caller-supplied, so a non-contract address or a revert
    ///      inside it propagates out. The Hub address is not, but once a threshold is crossed, or on
    ///      a closed band, this reads `Hub.totalAssets()`, which reverts whenever any YieldGroup's
    ///      valuation does. Not pausing then costs nothing: every Hub deposit and redemption is
    ///      priced from that same read, so they revert too.
    /// @param yieldGroup The YieldGroup holding the resource
    /// @param resource The resource whose NavGuard band to read
    /// @return status Why a pause is or is not due
    /// @return hub The Hub that would be paused, as governance configured it; `0` when unwatched
    /// @return observedValue Value the counterparty reports, in asset units; `0` if unread or empty
    /// @return centre What the band says the position is worth, drift included; `0` if unread or closed
    /// @return minAllowedValue The band's floor; `0` before it is read, or when the band is closed
    /// @return maxAllowedValue The band's cap; `0` before it is read, or when the band is closed
    function checkNavGuardDeviation(
        address yieldGroup,
        address resource
    )
        public
        view
        returns (
            NavGuardCheckStatus status,
            address hub,
            uint256 observedValue,
            uint256 centre,
            uint256 minAllowedValue,
            uint256 maxAllowedValue
        )
    {
        NavGuardConfig memory config = navGuardConfigs[yieldGroup][resource];
        if (!config.enabled) return (NavGuardCheckStatus.MonitoringDisabled, address(0), 0, 0, 0, 0);

        hub = config.hub;

        if (!IHub(hub).yieldGroupConfig(yieldGroup).registered) {
            return (NavGuardCheckStatus.YieldGroupNotRegistered, hub, 0, 0, 0, 0);
        }

        (bool registered, , ) = IYieldGroupNav(yieldGroup).resourceConfig(resource);
        if (!registered) return (NavGuardCheckStatus.ResourceNotRegistered, hub, 0, 0, 0, 0);

        (observedValue, minAllowedValue, maxAllowedValue, , ) = IYieldGroupNav(yieldGroup).navGuardStatus(resource);

        // Our pause thresholds are measured from the centre, not the Hub's min and max, because those
        // include the Hub's own gap and would shift our thresholds whenever that gap is changed.
        IYieldGroupNav.NavBand memory band = IYieldGroupNav(yieldGroup).navGuard(resource);

        // The centre grows by `driftBps` a year but is only saved on a deposit, redeem or re-anchor,
        // so add the growth since `driftFrom`, the same way the Hub's `NavGuard._grown` does.
        uint256 drift = (uint256(band.centre) * band.driftBps * (block.timestamp - band.driftFrom)) /
            (uint256(MAX_DEVIATION_BPS) * 365 days);
        centre = band.centre + drift;

        // Two zero cases are handled first, as the percentage check below would pause on either:
        // - `observedValue` is 0 when unreadable or priced at nothing, which is below every threshold.
        // - `centre` is 0 after a full exit closes the band, which makes every threshold 0.
        if (observedValue == 0) {
            return (
                NavGuardCheckStatus.ObservedValueZero,
                hub,
                observedValue,
                centre,
                minAllowedValue,
                maxAllowedValue
            );
        }
        if (centre == 0) {
            // The band is closed but the position still reports a value. With the cap on, the Hub
            // values it at 0, so Hub NAV is short by `observedValue`. That pauses only if the
            // downside is watched and the shortfall is over `minHubNavGapBps` of Hub NAV, so dust
            // cannot freeze the Hub.
            bool closedBandBreached = band.capEnabled &&
                config.pauseDownBps != 0 &&
                _exceedsMinHubNavGap(hub, observedValue);

            status = closedBandBreached ? NavGuardCheckStatus.Breached : NavGuardCheckStatus.CentreZero;
            return (status, hub, observedValue, centre, minAllowedValue, maxAllowedValue);
        }

        uint256 downTripPoint = (centre * (MAX_DEVIATION_BPS - config.pauseDownBps)) / MAX_DEVIATION_BPS;
        uint256 upTripPoint = (centre * (MAX_DEVIATION_BPS + config.pauseUpBps)) / MAX_DEVIATION_BPS;

        // A threshold of 0 means that side is off, not that it pauses on any move.
        bool breachedDown = config.pauseDownBps != 0 && observedValue < downTripPoint;
        bool breachedUp = config.pauseUpBps != 0 && observedValue > upTripPoint;

        // Crossing a threshold is not enough: the gap must also be over `minHubNavGapBps` of the
        // Hub's NAV, the same test a closed band gets. The side that crossed puts `observedValue`
        // above or below the centre, so the subtraction cannot underflow.
        bool breached = (breachedDown || breachedUp) &&
            _exceedsMinHubNavGap(hub, breachedUp ? observedValue - centre : centre - observedValue);

        status = breached ? NavGuardCheckStatus.Breached : NavGuardCheckStatus.WithinThreshold;
    }

    /// @notice Whether a gap is big enough, next to the Hub's NAV, to pause the Hub for
    /// @dev Reverts whenever `Hub.totalAssets()` does.
    /// @param hub The Hub whose NAV the gap is measured against
    /// @param gap Distance between the observed value and the centre, in asset units
    /// @return Whether `gap` is over `minHubNavGapBps` of the Hub's NAV
    function _exceedsMinHubNavGap(address hub, uint256 gap) private view returns (bool) {
        return gap > (IHub(hub).totalAssets() * minHubNavGapBps) / MAX_DEVIATION_BPS;
    }

    /// @notice Resolve a YieldGroup's Hub and prove the whole chain down to the resource is live
    /// @dev Three reads, each covering what the one before cannot: the registry vouches for the
    ///      Hub, the Hub for the YieldGroup, and the YieldGroup for the resource.
    /// @param yieldGroup YieldGroup to resolve
    /// @param resource Resource that must belong to it
    /// @return hub The Hub that YieldGroup reports to
    function _requireLiveResource(address yieldGroup, address resource) private view returns (address hub) {
        hub = IYieldGroupNav(yieldGroup).hub();
        if (!HUB_REGISTRY.isHub(hub)) revert HubNotRegistered(hub, yieldGroup);
        if (!IHub(hub).yieldGroupConfig(yieldGroup).registered) revert YieldGroupNotRegistered(hub, yieldGroup);

        (bool registered, , ) = IYieldGroupNav(yieldGroup).resourceConfig(resource);
        if (!registered) revert ResourceNotRegistered(yieldGroup, resource);
    }
}

contracts/EmergencyBrake/IEBrake.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { IComptroller } from "../Interfaces/IComptroller.sol";

/**
 * @title IEBrake
 * @author Venus Protocol
 * @notice Interface for the EBrake (Emergency Brake) contract.
 *         EBrake is an emergency action router that can only TIGHTEN restrictions,
 *         never loosen them. It also snapshots pre-incident values (CF, caps) so that
 *         governance can read and restore them via VIP. See resetCFSnapshot() / resetCapSnapshot().
 *
 * @dev Design goals and integration patterns:
 *
 *   1. DIRECT ACCESS
 *      The Venus multisig is whitelisted. During an incident, the multisig can call
 *      any function here (pause, set caps, etc.) without going through governance.
 *
 *   2. ON-CHAIN MONITORING CONTRACTS
 *      Contracts like DeviationSentinel or any Venus monitoring contract are also whitelisted.
 *      They contain their own detection logic (e.g. price deviation checks) and call into EBrake
 *      when a threat is detected. Example: DeviationSentinel detects a price anomaly → calls
 *      EBrake.pauseSupply() or EBrake.decreaseCF(). The detection logic stays isolated in
 *      the monitor; EBrake only handles execution.
 *
 *   3. THIRD-PARTY MONITORS VIA SAFE MODULES
 *      External monitoring services (e.g. Hypernative) don't get direct whitelist access. Instead,
 *      for each service we create a dedicated Safe Module on our multisig. The Safe Module contains
 *      its own allowlist of which EBrake functions that service can call (e.g. Hypernative can only
 *      pause supply/borrow, not set caps). This keeps permission scoping outside of EBrake — each
 *      module enforces its own restrictions.
 *
 *   SAFETY INVARIANT — "Do no harm to existing users":
 *
 *      This contract can ONLY tighten restrictions, NEVER loosen them. If a whitelisted address
 *      is compromised, the worst outcome is a temporary freeze — never fund loss or liquidation.
 *
 *      This contract intentionally CANNOT:
 *        - Unpause             → EBrake can only pause, never unpause. Recovery is via governance VIP
 *        - Pause REPAY         → users must always be able to repay to avoid liquidation
 *        - Pause SEIZE         → liquidations must always work to prevent bad debt accumulation
 *        - Pause protocol      → setProtocolPaused blocks repay + liquidation, same problem
 *        - Lower LT            → lowering liquidation threshold would instantly make healthy
 *                                 positions liquidatable, harming innocent users
 *        - Increase caps       → caps can only be decreased to reduce exposure, never increased
 *        - Enable forced       → bypasses shortfall check entirely — ANY borrower becomes
 *          liquidation            liquidatable even with healthy collateral ratio
 *        - Target individual   → prevents griefing specific addresses via per-user forced
 *          users                  liquidation
 *        - Set close factor    → increasing allows liquidators to seize larger portions of
 *                                 collateral in one tx
 *        - Change oracle       → wrong oracle = mass mispricing = mass liquidations
 *        - Change liquidation  → altering incentive changes liquidation economics for all users
 *          incentive
 *
 *      Worst-case if EBrake is compromised:
 *        - Pauses minting/borrowing/redeeming/transfers (inconvenient, no fund loss)
 *        - Zeros supply/borrow caps (blocks new positions, existing ones unaffected)
 *        - Decreases collateral factor (blocks new borrows against asset, does NOT liquidate
 *          existing positions — that requires LT change, which EBrake cannot do)
 *        - Pauses flash loans (blocks flash loan attack vector, no user impact)
 *        - Pauses the Liquidity Hub (blocks deposits and redemptions; existing balances
 *          untouched, and emergencyReallocate still works)
 *        - Pauses a Hub YieldGroup or one of its resources (stops new deposits routing there, and
 *          user withdrawals skip it; the balance already there still counts toward NAV)
 *      Recovery: Governance VIP restores all parameters. Temporary freeze, not catastrophic.
 *
 *   BSC vs NON-BSC DIFFERENCES:
 *
 *      The IS_ISOLATED_POOL immutable determines which comptroller ABI is used.
 *      It is set at deployment and cannot be changed.
 *
 *      BSC (BNB Chain) — Diamond Comptroller (IS_ISOLATED_POOL = false):
 *        - decreaseCF(market, newCF) — iterates corePoolId to lastPoolId, applies newCF only to
 *          pools where currentCF > newCF; silently skips pools already at or below newCF.
 *        - decreaseCF(market, poolId, newCF) — targets a single pool (e.g. multisig use)
 *        - Uses poolMarkets() (7-value return) to read LT,
 *          calls setCollateralFactor(poolId, market, newCF, LT) which returns uint256 error code
 *        - Supports e-mode pools via poolId > 0
 *        - pauseFlashLoan() — flash loans only exist on Diamond
 *        - pauseHub(hub), pauseHubYieldGroup(yieldGroup), pauseHubResource(yieldGroup, resource)
 *          — the Liquidity Hub is BSC-only
 *        - disablePoolBorrow(poolId, market) — per-pool granular borrow disable, only on Diamond
 *        - revokeFlashLoanAccess(account) — remove a single account from the flash loan
 *          whitelist; flash loan whitelist only exists on Diamond
 *        - ACM permission strings use underscore prefix:
 *          _setActionsPaused, _setMarketBorrowCaps, _setMarketSupplyCaps
 *
 *      Non-BSC chains — IL Comptroller (IS_ISOLATED_POOL = true):
 *        - decreaseCF(market, newCF) — uses markets() (3-value return) to read LT,
 *          calls setCollateralFactor(market, newCF, LT) which returns void (no error code).
 *          Reverts if newCF > currentCF.
 *        - No poolId concept — only the core pool exists (other pools are deprecated)
 *        - decreaseCF(market, poolId, newCF) not granted ACM permission (no pool concept on IL)
 *        - pauseFlashLoan() not granted ACM permission (flash loans don't exist on IL)
 *        - pauseHub(address), pauseHubYieldGroup(address) and
 *          pauseHubResource(address,address) not granted ACM permission (no Liquidity Hub off BSC).
 *          These are EBrake's own roles; what EBrake must hold on the Hub side is `pauseHub()` and
 *          `pauseYieldGroup(address)` on the Hub, and `pauseResource(address)` on each YieldGroup.
 *        - ACM permission strings have no underscore:
 *          setActionsPaused, setMarketBorrowCaps, setMarketSupplyCaps
 *
 *      All other functions (pauseActions, pauseSupply, pauseBorrow, pauseRedeem,
 *      pauseTransfer, setMarketBorrowCaps, setMarketSupplyCaps) are ABI-compatible
 *      across both comptroller types and work identically on all chains.
 */
interface IEBrake {
    // ═══════════════════════════════════════════════════════════════════════
    //                              EVENTS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Emitted when actions are paused on markets via batch pause.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses that were paused.
    /// @param actions The actions that were paused.
    event ActionsPaused(address indexed caller, address[] markets, IComptroller.Action[] actions);

    /// @notice Emitted when a single action is paused on a market.
    /// @param caller The address that triggered the emergency action.
    /// @param market The vToken market address that was paused.
    /// @param action The action that was paused.
    event ActionPaused(address indexed caller, address indexed market, IComptroller.Action action);

    /// @notice Emitted when flash loans are paused.
    /// @param caller The address that triggered the emergency action.
    event FlashLoanPaused(address indexed caller);

    /// @notice Emitted when borrowing is disabled for a market in a specific pool.
    /// @param caller The address that triggered the emergency action.
    /// @param poolId The pool identifier (0 = core pool, >0 = e-mode pools).
    /// @param market The vToken market address whose pool-borrow flag was disabled.
    event PoolBorrowDisabled(address indexed caller, uint96 indexed poolId, address indexed market);

    /// @notice Emitted when an account is removed from the flash loan whitelist.
    /// @param caller The address that triggered the emergency action.
    /// @param account The account whose flash loan access was revoked.
    event FlashLoanAccessRevoked(address indexed caller, address indexed account);

    /// @notice Emitted when a collateral factor is decreased.
    ///         Used for both core/e-mode pools and IL comptrollers.
    /// @param caller The address that triggered the emergency action.
    /// @param market The vToken market address whose CF was decreased.
    /// @param poolId The pool ID. On BNB Chain (Diamond comptroller) this identifies the core pool (0)
    ///        or an e-mode pool (>0). On other networks (IL comptroller) there is no poolId concept;
    ///        0 is used as a sentinel value to indicate that only the core pool is supported (other pools are deprecated).
    /// @param newCF The new collateral factor value that the market was set to.
    event CollateralFactorDecreased(
        address indexed caller,
        address indexed market,
        uint96 indexed poolId,
        uint256 newCF
    );

    /// @notice Emitted when borrow caps are decreased.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses whose borrow caps were decreased.
    /// @param newBorrowCaps The new borrow cap values.
    event BorrowCapsDecreased(address indexed caller, address[] markets, uint256[] newBorrowCaps);

    /// @notice Emitted when supply caps are decreased.
    /// @param caller The address that triggered the emergency action.
    /// @param markets The vToken market addresses whose supply caps were decreased.
    /// @param newSupplyCaps The new supply cap values.
    event SupplyCapsDecreased(address indexed caller, address[] markets, uint256[] newSupplyCaps);

    /// @notice Emitted when a market's CF/LT snapshot is reset after governance recovery.
    /// @param market The market address whose CF snapshot was cleared.
    event CFSnapshotReset(address indexed market);

    /// @notice Emitted when a market's borrow cap snapshot is reset after governance recovery.
    /// @param market The market address whose borrow cap snapshot was cleared.
    event BorrowCapSnapshotReset(address indexed market);

    /// @notice Emitted when a market's supply cap snapshot is reset after governance recovery.
    /// @param market The market address whose supply cap snapshot was cleared.
    event SupplyCapSnapshotReset(address indexed market);

    /// @notice Emitted when the Liquidity Hub was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param hub The Hub that was paused.
    event HubPaused(address indexed caller, address indexed hub);

    /// @notice Emitted when a Hub YieldGroup was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param hub The Hub the YieldGroup belongs to.
    /// @param yieldGroup The YieldGroup that was paused.
    event HubYieldGroupPaused(address indexed caller, address indexed hub, address indexed yieldGroup);

    /// @notice Emitted when a resource inside a Hub YieldGroup was paused through EBrake.
    /// @param caller The address that triggered the pause.
    /// @param yieldGroup The YieldGroup that holds the resource.
    /// @param resource The resource that was paused.
    event HubResourcePaused(address indexed caller, address indexed yieldGroup, address indexed resource);

    // ═══════════════════════════════════════════════════════════════════════
    //                              ERRORS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Thrown when a forbidden action (REPAY, SEIZE, etc.) is passed to batch pause.
    /// @param action The disallowed action that was passed.
    error ForbiddenAction(IComptroller.Action action);

    /// @notice Thrown when a zero address is passed where a valid address is required.
    error ZeroAddress();

    /// @notice Thrown when a market is not listed in the given pool.
    ///         On BNB Chain (Diamond comptroller) poolId identifies the core pool (0) or an e-mode pool (>0).
    ///         On other networks (IL comptroller) there is no poolId concept;
    ///         0 is used as a sentinel value (other pools are deprecated).
    /// @param poolId The pool ID that was queried.
    /// @param market The market address that is not listed.
    error MarketNotListed(uint96 poolId, address market);

    /// @notice Thrown when setCollateralFactor returns a non-zero error code.
    /// @param errorCode The error code returned by the comptroller.
    error SetCollateralFactorFailed(uint256 errorCode);

    /// @notice Thrown when an empty array is passed where at least one element is required.
    error EmptyArray();

    /// @notice Thrown when array lengths do not match.
    /// @param expected The expected array length.
    /// @param actual The actual array length.
    error ArrayLengthMismatch(uint256 expected, uint256 actual);

    /// @notice Thrown when the requested cap exceeds the current cap on the comptroller.
    /// @param market The market whose cap was attempted to be increased.
    /// @param currentCap The current cap value on the comptroller.
    /// @param requestedCap The new cap value that was rejected.
    error CapExceedsCurrent(address market, uint256 currentCap, uint256 requestedCap);

    /// @notice Thrown when a function is called that is not supported on IL (isolated-pool) comptrollers.
    ///         Pool ID is a Diamond-only concept — this function should never be ACM-granted on IL chains.
    error NotSupportedOnIsolatedPool();

    /// @notice Thrown when the requested collateral factor exceeds the current CF on the comptroller.
    ///         EBrake can only tighten CF — newCF must be <= currentCF.
    /// @param market The market whose CF was attempted to be increased.
    /// @param poolId The pool ID where the violation was detected (0 on IL comptroller).
    /// @param currentCF The current collateral factor on the comptroller.
    /// @param requestedCF The new CF value that was rejected.
    error CFExceedsCurrent(address market, uint96 poolId, uint256 currentCF, uint256 requestedCF);

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — BATCH OPERATIONS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Pause multiple actions on multiple markets in one call.
     * @dev Only MINT, REDEEM, BORROW, and TRANSFER are allowed. Reverts on REPAY, SEIZE,
     *      LIQUIDATE, ENTER_MARKET, or EXIT_MARKET — see SAFETY INVARIANT.
     * @param markets The vToken market addresses to pause actions on.
     * @param actions The actions to pause.
     */
    function pauseActions(address[] calldata markets, IComptroller.Action[] calldata actions) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — SINGLE MARKET PAUSING
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pause supply (mint) on a single market.
    ///         Blocks new deposits. Existing suppliers can still redeem.
    /// @param market The vToken market address.
    function pauseSupply(address market) external;

    /// @notice Pause redeem on a single market.
    ///         Blocks withdrawals. Use when draining must be stopped immediately.
    /// @param market The vToken market address.
    function pauseRedeem(address market) external;

    /// @notice Pause borrow on a single market.
    ///         Blocks new borrows. Existing borrowers can still repay.
    /// @param market The vToken market address.
    function pauseBorrow(address market) external;

    /// @notice Pause transfer of vTokens on a single market.
    ///         Blocks vToken movement, prevents attacker from moving stolen collateral.
    /// @param market The vToken market address.
    function pauseTransfer(address market) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — FLASH LOANS
    // ═══════════════════════════════════════════════════════════════════════

    /// @notice Pause flash loans across the core pool.
    function pauseFlashLoan() external;

    /**
     * @notice Disable borrowing for a market in a specific pool, leaving other pools unaffected.
     * @dev Only meaningful on Diamond comptroller (BSC) where the per-pool `isBorrowAllowed` flag exists.
     *      On non-BSC chains the underlying call will revert (selector mismatch on IL comptroller).
     *
     *      This is independent of `pauseBorrow(market)` which flips the global
     *      `_actionPaused[market][BORROW]` flag across every pool. Both flags must allow borrowing
     *      for borrows to actually proceed in a given pool/market — recovery from a combined
     *      tightening therefore requires governance to clear both flags.
     *
     *      The boolean argument is hardcoded to `false` inside the implementation to preserve
     *      the EBrake "tighten only, never loosen" invariant. Re-enabling borrow is governance-only.
     * @param poolId The pool identifier (0 = core pool, >0 = e-mode pools).
     * @param market The vToken market address.
     */
    function disablePoolBorrow(uint96 poolId, address market) external;

    /**
     * @notice Remove a single account from the flash loan whitelist.
     * @dev Only meaningful on Diamond comptroller (BSC) where the flash loan whitelist exists.
     *      On non-BSC chains the underlying call will revert (selector mismatch on IL comptroller).
     *
     *      This is the surgical alternative to `pauseFlashLoan()`, which kills flash loans for
     *      every whitelisted account. Use it when a single whitelisted integrator is compromised.
     *
     *      The boolean argument is hardcoded to `false` inside the implementation to preserve
     *      the EBrake "tighten only, never loosen" invariant. Re-granting access is governance-only.
     *
     *      Idempotent: if the account is not currently whitelisted, the call is a no-op and
     *      no event is emitted. FlashLoanAccessRevoked is a true state-change signal.
     * @param account The account whose flash loan access should be revoked.
     */
    function revokeFlashLoanAccess(address account) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — LIQUIDITY HUB
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Pause the Liquidity Hub, halting deposits and redemptions.
     * @dev Forwards to the Hub, which EBrake holds the `pauseHub()` ACM role on. Tighten-only —
     *      unpausing is a VIP against the Hub directly. An already-paused Hub is a no-op with no
     *      event, so {HubPaused} stays a true state-change signal, as {pauseFlashLoan} does.
     * @param hub The Liquidity Hub to pause.
     */
    function pauseHub(address hub) external;

    /**
     * @notice Stop a Hub routing new deposits to one YieldGroup. The balance already there still
     *         counts toward NAV, but user withdrawals skip it until governance unpauses it.
     * @dev Forwards to the Hub the YieldGroup reports through `hub()`, which EBrake holds the
     *      `pauseYieldGroup(address)` ACM role on. Tighten-only, and an already-paused YieldGroup is
     *      a no-op with no event, as {pauseHub}. A YieldGroup the Hub never registered reads as
     *      unpaused, so the Hub's own `YieldGroupNotRegistered` revert comes back to the caller —
     *      which is also what stops a fake YieldGroup that names a real Hub.
     * @param yieldGroup The YieldGroup to pause.
     */
    function pauseHubYieldGroup(address yieldGroup) external;

    /**
     * @notice Stop a Hub YieldGroup routing new deposits to one of its resources. The balance
     *         already there still counts toward NAV, but user withdrawals skip it until governance
     *         unpauses it.
     * @dev Forwards to the YieldGroup, which checks `pauseResource(address)` against its own
     *      address, so EBrake needs that grant on every YieldGroup it should reach. Tighten-only,
     *      and an already-paused resource is a no-op with no event, as {pauseHub}. A resource the
     *      YieldGroup never registered reads as unpaused, so its `ResourceNotRegistered` revert
     *      comes back to the caller.
     * @param yieldGroup The YieldGroup that holds the resource.
     * @param resource The resource to pause.
     */
    function pauseHubResource(address yieldGroup, address resource) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     EMERGENCY ACTIONS — RISK PARAMETER ADJUSTMENTS
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Decrease collateral factor to `newCF` for a market across all relevant pools.
     *         Liquidation threshold is left unchanged.
     *         Blocks/limits new borrows against the asset. Does NOT make existing positions liquidatable —
     *         that would require lowering LT, which this contract cannot do.
     * @dev On Diamond comptroller (IS_ISOLATED_POOL=false): iterates corePoolId to lastPoolId;
     *      applies `newCF` only to pools where currentCF > newCF (silently skips pools already
     *      at or below newCF and unlisted pools). Never reverts due to CF comparison — use the
     *      per-pool overload if you need strict enforcement on a specific pool.
     *      On IL comptroller (IS_ISOLATED_POOL=true): applies to the single market entry and
     *      reverts with CFExceedsCurrent if newCF > currentCF.
     * @param market The vToken market address whose CF should be decreased.
     * @param newCF The new collateral factor value. On Diamond, pools already at or below this
     *              value are silently skipped. On IL, must be <= current CF.
     */
    function decreaseCF(address market, uint256 newCF) external;

    /**
     * @notice Decrease collateral factor to `newCF` for a market in a specific pool.
     *         Same safety guarantees as decreaseCF(address,uint256) — LT is left unchanged.
     * @dev Only meaningful on Diamond comptroller (BSC) where multiple pools exist.
     *      Reverts with NotSupportedOnIsolatedPool on IL chains — ACM must not grant this permission there.
     *      Reverts with CFExceedsCurrent if newCF > current CF in the targeted pool.
     * @param market The vToken market address whose CF should be decreased.
     * @param poolId The pool ID (0 for core pool, >0 for e-mode pools).
     * @param newCF The new collateral factor value. Must be <= current CF in the targeted pool.
     */
    function decreaseCF(address market, uint96 poolId, uint256 newCF) external;

    /**
     * @notice Decrease borrow caps on markets. Each new cap must be strictly LOWER than the current value.
     *         Elements equal to the current cap are silently skipped. Setting to 0 blocks all new borrows.
     *         Existing borrows are never affected by caps.
     * @param markets The vToken market addresses to adjust borrow caps on.
     * @param newBorrowCaps The new borrow cap values. Each must be < current cap (equality is a no-op, > reverts).
     */
    function setMarketBorrowCaps(address[] calldata markets, uint256[] calldata newBorrowCaps) external;

    /**
     * @notice Decrease supply caps on markets. Each new cap must be strictly LOWER than the current value.
     *         Elements equal to the current cap are silently skipped. Setting to 0 blocks all new deposits.
     *         Existing deposits are never affected by caps.
     * @param markets The vToken market addresses to adjust supply caps on.
     * @param newSupplyCaps The new supply cap values. Each must be < current cap (equality is a no-op, > reverts).
     */
    function setMarketSupplyCaps(address[] calldata markets, uint256[] calldata newSupplyCaps) external;

    // ═══════════════════════════════════════════════════════════════════════
    //                     MARKET STATE SNAPSHOT — RESET & VIEW
    // ═══════════════════════════════════════════════════════════════════════

    /**
     * @notice Reset only the stored CF/LT snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring collateral factors.
     *      Clears per-pool CF/LT values so that future EBrake actions can capture fresh
     *      pre-incident values. Does not touch cap snapshots.
     * @param market The vToken market address whose CF snapshot should be cleared.
     */
    function resetCFSnapshot(address market) external;

    /**
     * @notice Reset only the stored borrow cap snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring the borrow cap.
     *      Clears borrowCap and borrowCapSnapshotted so that future EBrake actions can capture
     *      a fresh pre-incident value. Does not touch the supply cap or CF snapshots.
     * @param market The vToken market address whose borrow cap snapshot should be cleared.
     */
    function resetBorrowCapSnapshot(address market) external;

    /**
     * @notice Reset only the stored supply cap snapshot for a market.
     * @dev Called by governance as part of a recovery VIP after restoring the supply cap.
     *      Clears supplyCap and supplyCapSnapshotted so that future EBrake actions can capture
     *      a fresh pre-incident value. Does not touch the borrow cap or CF snapshots.
     * @param market The vToken market address whose supply cap snapshot should be cleared.
     */
    function resetSupplyCapSnapshot(address market) external;

    /**
     * @notice Read the stored collateral factor and liquidation threshold snapshot for a market in a specific pool.
     * @param market The vToken market address.
     * @param poolId The pool ID (0 for IL chains or core pool on Diamond).
     * @return cf The collateral factor that was stored before EBrake zeroed it. 0 if no snapshot exists.
     * @return lt The liquidation threshold at the time of the snapshot. 0 if no snapshot exists.
     */
    function getMarketCFSnapshot(address market, uint96 poolId) external view returns (uint256 cf, uint256 lt);
}

contracts/Interfaces/IComptroller.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

import { ResilientOracleInterface } from "@venusprotocol/oracle/contracts/interfaces/OracleInterface.sol";
import { IVToken } from "./IVToken.sol";

/// @title IComptroller
/// @author Venus Protocol
/// @notice Interface for the Venus Comptroller with market management and risk parameter functions.
interface IComptroller {
    enum Action {
        MINT,
        REDEEM,
        BORROW,
        REPAY,
        SEIZE,
        LIQUIDATE,
        TRANSFER,
        ENTER_MARKET,
        EXIT_MARKET
    }

    /// @notice Pause or unpause specific actions on given markets.
    /// @param markets_ The list of vToken market addresses.
    /// @param actions_ The list of actions to pause/unpause.
    /// @param paused_ True to pause, false to unpause.
    function setActionsPaused(address[] calldata markets_, Action[] calldata actions_, bool paused_) external;

    /// @notice Set borrow caps for the given markets.
    /// @param vTokens The list of vToken market addresses.
    /// @param newBorrowCaps The list of new borrow cap values.
    function setMarketBorrowCaps(address[] calldata vTokens, uint256[] calldata newBorrowCaps) external;

    /// @notice Set supply caps for the given markets.
    /// @param vTokens The list of vToken market addresses.
    /// @param newSupplyCaps The list of new supply cap values.
    function setMarketSupplyCaps(address[] calldata vTokens, uint256[] calldata newSupplyCaps) external;

    /// @notice Unlist a market from the comptroller.
    /// @param vToken The vToken market address to unlist.
    /// @return uint256 Error code (0 = success).
    function unlistMarket(address vToken) external returns (uint256);

    /// @notice Execute a flash loan.
    /// @param onBehalf The address on whose behalf the flash loan is executed.
    /// @param receiver The address receiving the flash loan funds.
    /// @param vTokens The list of vToken markets to borrow from.
    /// @param underlyingAmounts The list of underlying amounts to borrow.
    /// @param param Additional parameters for the flash loan callback.
    function executeFlashLoan(
        address payable onBehalf,
        address payable receiver,
        IVToken[] memory vTokens,
        uint256[] memory underlyingAmounts,
        bytes memory param
    ) external;

    /// @notice Enter multiple markets to use as collateral.
    /// @param vTokens The list of vToken market addresses to enter.
    /// @return uint256[] Error codes for each market (0 = success).
    function enterMarkets(address[] calldata vTokens) external returns (uint256[] memory);

    /// @notice Enter a market on behalf of another address.
    /// @param onBehalf The address to enter the market for.
    /// @param vToken The vToken market address.
    /// @return uint256 Error code (0 = success).
    function enterMarketBehalf(address onBehalf, address vToken) external returns (uint256);

    /// @notice Enter a market for a specific user (internal comptroller use).
    /// @param user The user address.
    /// @param vToken The vToken market address.
    /// @return uint256 Error code (0 = success).
    function enterMarket(address user, address vToken) external returns (uint256);

    /// @notice Check whether an action is paused on a given market.
    /// @param market The vToken market address.
    /// @param action The action to check.
    /// @return bool True if the action is paused.
    function actionPaused(address market, Action action) external view returns (bool);

    /// @notice Get market information for a given vToken.
    /// @param vToken The vToken market address.
    /// @return isListed Whether the market is listed.
    /// @return collateralFactorMantissa The collateral factor mantissa.
    /// @return isComped Whether the market receives COMP/XVS rewards.
    function markets(
        address vToken
    ) external view returns (bool isListed, uint256 collateralFactorMantissa, bool isComped);

    /// @notice Get the price oracle used by the comptroller.
    /// @return ResilientOracleInterface The oracle contract.
    function oracle() external view returns (ResilientOracleInterface);

    /// @notice Check if an account has entered a given market.
    /// @param account The account address.
    /// @param vToken The vToken market to check membership for.
    /// @return bool True if the account is a member of the market.
    function checkMembership(address account, IVToken vToken) external view returns (bool);

    /// @notice Get the borrowing power of an account.
    /// @param account The account address.
    /// @return error Error code (0 = success).
    /// @return liquidity The account's excess liquidity.
    /// @return shortfall The account's shortfall.
    function getBorrowingPower(
        address account
    ) external view returns (uint256 error, uint256 liquidity, uint256 shortfall);

    /// @notice Get the treasury fee percentage.
    /// @return uint256 The treasury percentage mantissa.
    function treasuryPercent() external view returns (uint256);

    /// @notice Get the borrow cap for a given market.
    /// @param vToken The vToken market address.
    /// @return uint256 The borrow cap.
    function borrowCaps(address vToken) external view returns (uint256);

    /// @notice Get the supply cap for a given market.
    /// @param vToken The vToken market address.
    /// @return uint256 The supply cap.
    function supplyCaps(address vToken) external view returns (uint256);

    /// @notice Check if a delegate is approved to borrow on behalf of a borrower.
    /// @param borrower The borrower address.
    /// @param delegate The delegate address.
    /// @return bool True if the delegate is approved.
    function approvedDelegates(address borrower, address delegate) external view returns (bool);

    function getAccountLiquidity(address account) external view returns (uint256, uint256, uint256);

    function exitMarket(address vToken) external returns (uint256);

    function updateDelegate(address delegate, bool approved) external;
}

contracts/Interfaces/IHubLiquidity.sol.content:
// SPDX-License-Identifier: BSD-3-Clause
pragma solidity ^0.8.25;

/**
 * @title IHubLiquidity
 * @author Venus
 * @notice Minimal views and emergency levers HubNavDeviationSentinel and EBrake need from the
 *         Liquidity Hub.
 * @dev Hand-copied so this repo takes no dependency on liquidity-hub. Nothing cross-checks the
 *      selectors at build time, so a signature that drifts from the Hub's reverts on chain.
 */
interface IHub {
    /// @notice Per-YieldGroup configuration held by the Hub's registry.
    /// @param absoluteCap Hard cap on the YieldGroup's holdings, in asset units.
    /// @param percentageCapBps Cap as a fraction of `totalAssets()`, in basis points.
    /// @param paused When true, routing skips this YieldGroup; existing balance still counts.
    /// @param registered True iff present in the Hub's YieldGroup registry.
    struct YieldGroupConfig {
        uint256 absoluteCap;
        uint16 percentageCapBps;
        bool paused;
        bool registered;
    }

    /// @notice Pause the Hub, halting deposits and redemptions.
    /// @dev ACM role `"pauseHub()"`. Idempotent — pausing an already-paused Hub is a silent no-op.
    function pauseHub() external;

    /// @notice Stop the Hub routing new deposits to a YieldGroup; its balance still counts toward NAV.
    /// @dev ACM role `"pauseYieldGroup(address)"`. Idempotent, and reverts `YieldGroupNotRegistered`
    ///      for an address the Hub never registered.
    /// @param yieldGroup YieldGroup to pause.
    function pauseYieldGroup(address yieldGroup) external;

    /// @notice Read a YieldGroup's registry entry.
    /// @param yieldGroup YieldGroup to read.
    /// @return config Stored configuration; all-zero when never registered.
    function yieldGroupConfig(address yieldGroup) external view returns (YieldGroupConfig memory config);

    /// @notice Total assets the Hub reports, with every NavGuard band applied.
    /// @return total Hub NAV, in asset units.
    function totalAssets() external view returns (uint256 total);

    /// @notice Whether the Hub is currently paused.
    /// @return paused True while the Hub is paused.
    function hubPaused() external view returns (bool paused);
}

/**
 * @title IHubRegistry
 * @author Venus
 * @notice The chain-level Hub directory, as far as HubNavDeviationSentinel needs it.
 * @dev One per chain, and only on chains that run a Liquidity Hub. Governance writes it, so it
 *      answers whether an address is a Hub Venus onboarded rather than one that claims to be.
 */
interface IHubRegistry {
    /// @notice Whether an address is a registered Hub.
    /// @param hub Address to check.
    /// @return registered True iff the registry lists `hub`.
    function isHub(address hub) external view returns (bool registered);
}

/**
 * @title IYieldGroupNav
 * @author Venus
 * @notice The registry and NavGuard reads HubNavDeviationSentinel needs from a YieldGroup, and the
 *         resource pause EBrake forwards to it.
 */
interface IYieldGroupNav {
    /// @notice A resource's NavGuard band, as stored by the YieldGroup.
    /// @param anchor Value the two gaps are sized off.
    /// @param centre Where the band sits: the anchor plus Venus's own deposits since.
    /// @param anchoredAt When the band last re-anchored.
    /// @param driftFrom When the drift clock last restarted.
    /// @param interval Seconds between re-anchors; `0` means no band is configured.
    /// @param driftBps Annual drift allowance, in basis points.
    /// @param upGapBps How far above the centre the band reaches, in basis points of the anchor.
    /// @param downGapBps How far below the centre the band reaches, in basis points of the anchor.
    /// @param capEnabled Whether the Hub holds its valuation to the cap.
    /// @param floorEnabled Whether the Hub holds its valuation to the floor.
    struct NavBand {
        uint128 anchor;
        uint128 centre;
        uint64 anchoredAt;
        uint64 driftFrom;
        uint32 interval;
        uint16 driftBps;
        uint16 upGapBps;
        uint16 downGapBps;
        bool capEnabled;
        bool floorEnabled;
    }

    /// @notice The Hub this YieldGroup reports assets to.
    /// @dev Written once in the YieldGroup's initializer, so HubNavDeviationSentinel can derive the Hub
    ///      from the YieldGroup instead of having a keeper name it.
    /// @return hubAddress Hub that owns this YieldGroup.
    function hub() external view returns (address hubAddress);

    /// @notice Per-resource registration / pause state plus the adapter handling it.
    /// @param resource Address to look up.
    /// @return registered True iff present in the YieldGroup's resource registry.
    /// @return paused True iff this resource is paused.
    /// @return adapter `IResourceAdapter` implementation bound to this resource.
    function resourceConfig(address resource) external view returns (bool registered, bool paused, address adapter);

    /// @notice Stop the YieldGroup routing new deposits to a resource; its balance still counts
    ///         toward NAV, but user withdrawals skip it.
    /// @dev ACM role `"pauseResource(address)"`, checked against this YieldGroup's address. Idempotent,
    ///      and reverts `ResourceNotRegistered` for an address the YieldGroup never registered.
    /// @param resource Resource to pause.
    function pauseResource(address resource) external;

    /// @notice The band's own stored numbers for a resource.
    /// @dev Field order must match the Hub's `NavBand` exactly. `anchor` and `centre` are both
    ///      `uint128` and adjacent, so a reordering there would decode silently wrong rather than
    ///      revert — pin this against `INavGuard.NavBand` when upgrading either side.
    ///
    ///      `centre` is the value as last saved, on a deposit, redeem or re-anchor. The Hub grows it
    ///      by `driftBps` a year since `driftFrom`, so a caller wanting the live centre must too.
    /// @param resource Resource to look up.
    /// @return band The stored band.
    function navGuard(address resource) external view returns (NavBand memory band);

    /// @notice Where a resource's value stands against its NavGuard band right now.
    /// @dev Never reverts. A zero `observedValue` is ambiguous on purpose: the Hub reads the value
    ///      source as `(value, readable)` and drops the flag here, so a read that failed and a
    ///      position the counterparty prices at nothing arrive identically. Neither can be told from
    ///      the other through this interface, which is why HubNavDeviationSentinel treats a zero as no
    ///      verdict rather than as a total loss.
    /// @param resource Resource to read.
    /// @return observedValue Value the counterparty reports, in asset units; `0` if unreadable or genuinely zero.
    /// @return minAllowedValue Lowest value the band allows right now.
    /// @return maxAllowedValue Highest value the band allows right now.
    /// @return isClamped Whether valuation is currently reporting a bound instead of `observedValue`.
    /// @return clampedValue What valuation reports instead; `0` when `isClamped` is false.
    function navGuardStatus(
        address resource
    )
        external
        view
        returns (
            uint256 observedValue,
            uint256 minAllowedValue,
            uint256 maxAllowedValue,
            bool isClamped,
            uint256 clampedValue
        );
}

contracts/Interfaces/IVToken.sol.content:
pragma solidity ^0.8.25;

import { IERC20Upgradeable } from "@openzeppelin/contracts-upgradeable/token/ERC20/IERC20Upgradeable.sol";
import { IComptroller } from "./IComptroller.sol";

interface IVToken is IERC20Upgradeable {
    function accrueInterest() external returns (uint256);

    function redeem(uint256 redeemTokens) external returns (uint256);

    function redeemUnderlying(uint256 redeemAmount) external returns (uint256);

    function borrowBalanceCurrent(address borrower) external returns (uint256);

    function balanceOfUnderlying(address owner) external returns (uint256);

    function seize(address liquidator, address borrower, uint seizeTokens) external returns (uint);

    function mintBehalf(address receiver, uint mintAmount) external returns (uint);

    function borrowBehalf(address borrower, uint borrowAmount) external returns (uint256);

    function comptroller() external view returns (IComptroller);

    function borrowBalanceStored(address account) external view returns (uint256);

    function underlying() external view returns (address);

    function totalBorrows() external view returns (uint256);

    function totalBorrowsCurrent() external returns (uint256);

    function exchangeRateCurrent() external returns (uint256);

    function exchangeRateStored() external view returns (uint256);

    function repayBorrowBehalf(address borrower, uint repayAmount) external returns (uint256);

    function redeemUnderlyingBehalf(address redeemer, uint redeemAmount) external returns (uint);

    function redeemBehalf(address redeemer, uint redeemTokens) external returns (uint);
}
